const { google } = require('googleapis');
const fs = require('fs');

const credentials = JSON.parse(fs.readFileSync('/root/auth/gmail/credentials.json', 'utf8'));
const tokens = JSON.parse(fs.readFileSync('/root/auth/gmail/tokens.json', 'utf8'));

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts.default;

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
  scope: account.scope,
  token_type: 'Bearer',
  expiry_date: 1000  // Force refresh
});

// Listen for new tokens
oauth2Client.on('tokens', (tokens) => {
  console.log('New tokens received:', JSON.stringify({scope: tokens.scope, expiry: tokens.expiry_date}));
});

const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

gmail.users.getProfile({ userId: 'me' }).then(res => {
  console.log('Profile:', JSON.stringify(res.data));
}).catch(err => {
  console.error('Error:', err.message);
  console.error('Full error:', JSON.stringify(err.response?.data || {}));
});
